import{_ as a}from"./chunks/chauffeur-workspace.Dz09cZIH.js";import{_ as r,o as t,c as o,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"Chauffeur workspace","description":"","frontmatter":{},"headers":[],"relativePath":"plus/chauffeur-workspace.md","filePath":"plus/chauffeur-workspace.md"}'),n={name:"plus/chauffeur-workspace.md"};function s(l,e,c,u,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="chauffeur-workspace" tabindex="-1">Chauffeur workspace <a class="header-anchor" href="#chauffeur-workspace" aria-label="Permalink to &quot;Chauffeur workspace&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>TransferBook+ v0.7.9 source-reviewed draft. Availability depends on the installed release, permissions and configuration; no commercial activation is asserted.</p></div><h2 id="illustrated-workspace" tabindex="-1">Illustrated workspace <a class="header-anchor" href="#illustrated-workspace" aria-label="Permalink to &quot;Illustrated workspace&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/chauffeur-workspace.png"><img src="'+a+'" alt="Chauffeur execution workspace shown from the administrator view: review the assignment, pickup brief and operational notes before accepting a job."></a></p><p><em>Select the screenshot to open it at its original size. Use your browser’s Back button to return.</em></p><p><em>Chauffeur execution workspace shown from the administrator view: review the assignment, pickup brief and operational notes before accepting a job.</em></p><p>Staging capture, TransferBook+ v0.7.11; English UI. Illustrative test data. This image does not establish production availability. Identifiers masked.</p><p>Inspect assigned trips and record permitted trip progress and operational notes.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>Use an approved workspace, confirm your company and role, and use synthetic records for training.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><ol><li>Sign in using an authorized driver account in an approved environment. In a demonstration, a driver selector is only a simulated identity, not authentication.</li><li>Review assigned reservation details, pickup time and location. Use the available trip-progress action only when the actual journey reaches that step.</li><li>Add a concise operational note when necessary. Use the airport greeting tablet sign only for the assigned guest and avoid exposing it unnecessarily.</li></ol><h2 id="verification-and-troubleshooting" tabindex="-1">Verification and troubleshooting <a class="header-anchor" href="#verification-and-troubleshooting" aria-label="Permalink to &quot;Verification and troubleshooting&quot;">​</a></h2><p>If a trip is missing or a progress action is unavailable, contact dispatch. Do not use another driver identity or assume a progress update transmits an external notification.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="/plus/">Operator Manual</a></li><li><a href="/plus/reservations.html">Reservations</a></li><li><a href="/plus/dispatch-schedule.html">Dispatch schedule</a></li></ul><h2 id="v0-7-26-journey-leg-operations" tabindex="-1">v0.7.26 journey-leg operations <a class="header-anchor" href="#v0-7-26-journey-leg-operations" aria-label="Permalink to &quot;v0.7.26 journey-leg operations&quot;">​</a></h2><p>Sign in with the actual authorized driver account. Review each assigned outbound or return task, accept or reject through the supported workflow and advance only the correct leg. Do not advance the return merely because the outbound is complete. Confirm current pickup brief and any reviewed arrival advisory. If GPS sharing is available and approved, use explicit opt-in while on duty and stop when no longer authorized. If the session is expired or offline, restore authorized access before submitting changes.</p><p>For partial or full cash received, use <a href="/plus/cash-management.html">Cash management</a>; physical office handover is separate. See <a href="/plus/arrival-intelligence.html">Arrival intelligence</a> and <a href="/plus/staff-administration.html">Staff administration</a>.</p>',19)])])}const g=r(n,[["render",s]]);export{m as __pageData,g as default};
